function isAnagram(s, t) {
  if (s.length !== t.length) return false
  const counts = new Map()
  for (const ch of s) counts.set(ch, (counts.get(ch) ?? 0) + 1)
  for (const ch of t) {
    const c = counts.get(ch) ?? 0
    if (c === 0) return false
    counts.set(ch, c - 1)
  }
  return true
}

solution.python:
def is_anagram(s, t):
    if len(s) != len(t):
        return False
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in t:
        if counts.get(ch, 0) == 0:
            return False
        counts[ch] -= 1
    return True

